/**
 * Parses and checks an Excel workbook (`.xlsx`, at most 10 MB, at most 2,000 plots, 3,000 members, 6,000 ownership
 * rows, 2,000 meter rows and 6,000 opening balance rows) and
 * returns a preview. Nothing is saved except the record of the upload itself. The preview can be committed for
 * 30 minutes (`expiresAt`) when `committable` is true, that is when there are no problems and something would be
 * created or updated. Requires the `IMPORT_RUN` permission; the platform operator has no cooperative data: 403.
 *
 * All five sheets are checked. The `Members`, `Ownership`, `Meters` and `Opening balances` sheets may be missing
 * (a file may hold plots only, or plots and members); the `Plots` sheet is required.
 * Rows whose first cell starts with `#` and empty rows are skipped. `problems` lists at most 1,000 problems
 * (`problemCount` is the total) in sheet and row order. `row` is the Excel row number (1 is the header row);
 * 0 means the problem is about the file or the whole sheet. `column` is the canonical column key
 * (Plots: `number`, `street`, `kind`, `area_m2`, `area_sotky`, `cadastral_number`, `has_building`, `notes`,
 * `water`;
 * Members: `external_id`, `last_name`, `first_name`, `middle_name`, `phones`, `email`, `postal_address`,
 * `delivery_channel`, `telegram_username`, `viber_phone`;
 * Ownership: `plot_number`, `member_external_id`, `share`, `valid_from`;
 * Meters: `plot_number`, `resource`, `serial`, `installed_on`, `initial_reading`;
 * Opening balances (sheet `OPENING_BALANCES`): `plot_number`, `charge_type`, `amount`, `date`, `reason`).
 * `code` is one of:
 *
 * - file and sheet level: `SHEET_MISSING` (no sheet of that name), `HEADER_MISSING` (a required column is not in
 *   the header row; `column` names it);
 * - cell level: `DATE_INVALID`, `NUMBER_INVALID`, `YES_NO_INVALID`, `AREA_BOTH_OR_NONE` (exactly one of
 *   `area_m2` and `area_sotky` must be filled for a new plot);
 * - plot rules, as when a plot is entered by hand: `REQUIRED`, `TOO_LONG`, `INVALID`, `AREA_INVALID`,
 *   `CADASTRAL_INVALID`, `CADASTRAL_NUMBER_TAKEN`, `PLOT_HAS_OWNERSHIP_HISTORY`, `PLOT_HAS_METER` (`kind`: a
 *   plot that has a meter cannot become common land);
 * - member rules, as when a member is entered by hand: `REQUIRED`, `TOO_LONG`, `INVALID` (an e-mail that is
 *   not an address, an unknown `delivery_channel`), `PHONE_INVALID` (`phones` or `viber_phone`),
 *   `CHANNEL_CONTACT_MISSING` (the contact the delivery channel needs is empty: `email`, `telegram_username` or
 *   `viber_phone`);
 * - member matching: `MEMBER_KEY_MISSING` (`email`: the row has neither an e-mail nor a phone, so a later import
 *   could not recognise the member), `MEMBER_AMBIGUOUS` (`phones`: the last name, first name and first phone match
 *   two or more members), `EMAIL_TAKEN` (`email`: the e-mail belongs to a member other than the one the name and
 *   first phone identify);
 * - `DUPLICATE_IN_FILE`: the plot number, or the member `external_id`, `email` or last name, first name and first
 *   phone (ignoring case), appears in an earlier row of the same sheet; also a row that matches the same existing
 *   member as an earlier row.
 *
 * Members are matched among the active members: by e-mail when the row has one, otherwise by last name, first
 * name and first phone (phones are compared in international format). A blank cell leaves the existing value
 * unchanged; a filled `phones` cell replaces the phones. At most 3,000 member rows.
 *
 * The `Ownership` sheet lists the current owners of plots: all four columns are required, one row per owner, all
 * rows of one plot carry the same `valid_from` (owner since). `member_external_id` is the `external_id` of a row
 * of the `Members` sheet (ignoring case); `plot_number` is a plot of the `Plots` sheet or an active plot of the
 * cooperative; `share` is a fraction `n/d` (`1/2`, `2/3`; a bare `1` is the whole plot). Ownership codes:
 *
 * - `UNKNOWN_MEMBER_KEY` (`member_external_id`: no row of the `Members` sheet has this key). A key whose
 *   `Members` row has a problem is not reported again; fix the `Members` row first;
 * - `UNKNOWN_PLOT` (`plot_number`: neither a plot of the `Plots` sheet nor an active plot);
 * - `PLOT_COMMON_LAND` (`plot_number`: common land has no owners);
 * - `REQUIRED` (`plot_number`, `member_external_id`, `share`, `valid_from`), `SHARE_INVALID` (`share`),
 *   `DATE_INVALID` (`valid_from` is not an Excel date or `DD.MM.YYYY`);
 * - `OWNERSHIP_DATE_INVALID` (`valid_from`: after today in Europe/Kyiv, or not later than the end of a previous
 *   owner of the plot);
 * - `OWNERSHIP_DATE_MISMATCH` (`valid_from`: differs from the date of the plot's first row);
 * - `DUPLICATE_OWNER` (`member_external_id`: the same member twice on one plot, reported on the later row);
 * - `SHARES_NOT_ONE` (`share`, first row of the plot: the shares do not add up to exactly 1);
 * - `OWNERSHIP_CONFLICT` (`plot_number`, first row of the plot, `params.plot`: the plot already has other current
 *   owners than the file's; the import never changes existing ownership, use "Change owner").
 *
 * A plot without a current owner gets the file's owners (counted as created ownership rows). A plot whose current
 * owners are exactly the file's members and shares, the dates ignored, is skipped (counted as unchanged). A plot
 * whose own `Plots` row has a problem, and a plot with a row whose member has a problem, is not checked further.
 * Ownership is never updated, so `ownerships.updated` is always 0. At most 6,000 ownership rows.
 *
 * The `Meters` sheet (Ukrainian name `Лічильники`) adds plot meters only; the tree of electricity meters is set
 * up on its own screen. All five columns are required, one row per meter: `plot_number` (a plot of the `Plots`
 * sheet or an active plot of the cooperative), `resource` (`ELECTRICITY` or `WATER`, in Ukrainian
 * `ЕЛЕКТРОЕНЕРГІЯ` or `ВОДА`), `serial` (at most 50 characters), `installed_on` (an Excel date or `DD.MM.YYYY`)
 * and `initial_reading` (the reading on the installation date: not negative, at most 11 integer digits and 3
 * decimals). A row whose plot already has an active meter of the resource with the same serial number (ignoring
 * case) is unchanged (`meters.unchanged`; its dates and reading are not compared), any other row creates an
 * active meter (`meters.created`). Meters are never updated, so `meters.updated` is always 0. Meter codes:
 *
 * - `UNKNOWN_PLOT`, `PLOT_COMMON_LAND` (`plot_number`), as on the `Ownership` sheet; a plot whose own `Plots` row
 *   has a problem is not checked further;
 * - `REQUIRED` (any column), `INVALID` (`resource`: not a resource word), `TOO_LONG` (`serial`),
 *   `DATE_INVALID` (`installed_on`), `NUMBER_INVALID` (`initial_reading`: not a number),
 *   `METER_VALUE_INVALID` (`initial_reading`: negative, more than 3 decimals or more than 11 integer digits);
 * - `READING_DATE_IN_FUTURE` (`installed_on`: after today in Europe/Kyiv);
 * - `DUPLICATE_IN_FILE` (`resource`: an earlier row names the same plot and resource);
 * - `METER_ACTIVE_EXISTS` (`serial`, `params.plot`: the plot already has another active meter of that resource;
 *   the import never replaces a meter, replace it in the register).
 *
 * The optional `water` column of the `Plots` sheet (Ukrainian header `Вода`) connects plots to water from the
 * day of the commit (Europe/Kyiv): `yes` (`так`, `true`) connects the plot to the cooperative's water supply; the
 * name of an active common consumer meter (a well, ignoring case and extra spaces) connects it to that source;
 * `no` (`ні`, `false`) and an empty cell leave the plot as it is: the import never disconnects a plot (that is
 * done on the plot card or the water source). A plot that already has a lasting connection is unchanged for
 * `yes` and for the name of its current source (`waterConnections.unchanged`); a new connection counts as
 * `waterConnections.created`; connections are never updated. Water codes (`water`):
 *
 * - `WATER_SOURCE_INVALID`: no active common consumer meter has this name;
 * - `WATER_SOURCE_AMBIGUOUS`: two or more active common consumer meters have this name;
 * - `WATER_ALREADY_CONNECTED`: the plot has a lasting connection to another source, or a connection that ends
 *   today or later;
 * - `PLOT_COMMON_LAND`: common land is not connected to water.
 * A plot whose own row has another problem is not checked for water.
 *
 * The `Opening balances` sheet (Ukrainian name `Вхідне сальдо`) books opening debts, one row per plot and charge
 * type, as when an opening balance is entered on the plot account: `plot_number` (a plot of the `Plots` sheet or
 * an active plot of the cooperative), `charge_type` (the name of a charge type as the cooperative calls it, or
 * the default name of a seeded type that was not renamed, in English or Ukrainian; ignoring case and extra
 * spaces), `amount` (greater than zero, at most two decimals), `date` (an Excel date or `DD.MM.YYYY`, not after
 * today in Europe/Kyiv; the balance is booked in the month of the date or the earliest open month after it) and
 * the optional `reason` (at most 500 characters; without one the import is the reference). The first four
 * columns are required. A row whose plot already has an opening balance of the same charge type, date and amount
 * that is not reversed is unchanged (`openingBalances.unchanged`), so uploading the same file again books
 * nothing twice; any other row books a new opening balance (`openingBalances.created`). Opening balances are
 * never updated. Codes:
 *
 * - `REQUIRED` (`plot_number`, `charge_type`, `amount`, `date`), `NUMBER_INVALID` (`amount`: not a number),
 *   `DATE_INVALID` (`date`), `TOO_LONG` (`reason`);
 * - `AMOUNT_NOT_POSITIVE` (`amount`: zero or negative), `INVALID` (`amount`: more than two decimals or more than
 *   12 integer digits; `charge_type`: the name stands for two charge types), `DATE_IN_FUTURE` (`date`);
 * - `UNKNOWN_PLOT`, `PLOT_COMMON_LAND` (`plot_number`), as on the `Meters` sheet;
 * - `UNKNOWN_CHARGE_TYPE` (`charge_type`: no charge type has this name), `CHARGE_TYPE_ARCHIVED` (`charge_type`:
 *   the only charge type with this name is archived);
 * - `DUPLICATE_IN_FILE` (`charge_type`: an earlier row names the same plot, charge type and date);
 * - `OPENING_BALANCE_EXISTS` (`amount`, `params.amount`: the plot already has an opening balance of this charge
 *   type and date with another amount that is not reversed; reverse it on the plot account first).
 *
 * A file that cannot be read at all is refused with 400 `FILE_NOT_XLSX` (not an `.xlsx` workbook, corrupt,
 * encrypted, or unpacking to an unreasonable size) or 400 `IMPORT_LIMIT_EXCEEDED` (too many rows); a file over
 * the size limit with 413 `FILE_TOO_LARGE`.
 * @summary Upload an import file and get its preview
 */
export const uploadImport = async (uploadImportBody: UploadImportBody, options?: Parameters<typeof nadelFetch>[1]): Promise<ImportPreview> => {
    const formData = new FormData();
formData.append(`file`, uploadImportBody.file);

  return nadelFetch<ImportPreview>(getUploadImportUrl(),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





